#include <zephyr/kernel.h>
#include <zephyr/mgmt/mcumgr/mgmt/mgmt.h>
#include <zephyr/mgmt/mcumgr/smp/smp.h>
#include <zephyr/mgmt/mcumgr/grp/enum_mgmt/enum_mgmt.h>
#include <zephyr/mgmt/mcumgr/mgmt/handlers.h>
#if defined(CONFIG_MCUMGR_MGMT_NOTIFICATION_HOOKS)
#include <zephyr/mgmt/mcumgr/mgmt/callbacks.h>
#endif
#include <zephyr/logging/log.h>

#include <mgmt/mcumgr/util/zcbor_bulk.h>
#include <mgmt/mcumgr/mgmt/mgmt_priv.h>

#include <zcbor_common.h>
#include <zcbor_decode.h>
#include <zcbor_encode.h>

LOG_MODULE_REGISTER(mcumgr_enum_grp, CONFIG_MCUMGR_GRP_ENUM_LOG_LEVEL);

/* Handles calculating the total number of supported command groups, note that this will read
 * cleanly regardless of if locking is enabled on the main task structure, because the registration
 * only occurs on startup before the SMP task is processed.
 */
static int enum_mgmt_count(struct smp_streamer *ctxt)
{
	uint16_t count = mgmt_groups_size();
	zcbor_state_t *zse = ctxt->writer->zs;
	bool ok;

	ok = zcbor_tstr_put_lit(zse, "count") &&
	     zcbor_uint32_put(zse, count);

	return ok ? MGMT_ERR_EOK : MGMT_ERR_EMSGSIZE;
}

struct enum_mgmt_list_cb_data {
	zcbor_state_t *zse;
	bool ok;
};

static bool enum_mgmt_list_cb(const struct mgmt_group *group, void *user_data)
{
	struct enum_mgmt_list_cb_data *data = (struct enum_mgmt_list_cb_data *)user_data;

	data->ok = zcbor_uint32_put(data->zse, (uint32_t)group->mg_group_id);

	return data->ok;
}

/* Lists all the supported command group IDs */
static int enum_mgmt_list(struct smp_streamer *ctxt)
{
	zcbor_state_t *zse = ctxt->writer->zs;
	uint16_t count = mgmt_groups_size();
	struct enum_mgmt_list_cb_data cb_data = {
		.zse = zse,
		.ok = true
	};

	if (!zcbor_tstr_put_lit(zse, "groups") ||
	    !zcbor_list_start_encode(zse, count)) {
		return MGMT_ERR_EMSGSIZE;
	}

	mgmt_groups_foreach(enum_mgmt_list_cb, &cb_data);

	if (!cb_data.ok || !zcbor_list_end_encode(zse, count)) {
		return MGMT_ERR_EMSGSIZE;
	}

	return MGMT_ERR_EOK;
}

struct enum_mgmt_single_cb_data {
	uint32_t index;
	uint32_t current;
	uint16_t group;
};

static bool enum_mgmt_single_cb(const struct mgmt_group *group, void *user_data)
{
	struct enum_mgmt_single_cb_data *data = (struct enum_mgmt_single_cb_data *)user_data;

	if (data->current == data->index) {
		data->group = group->mg_group_id;

		return false;
	}

	++data->current;

	return true;
}

/* Lists a single supported command group ID */
static int enum_mgmt_single(struct smp_streamer *ctxt)
{
	zcbor_state_t *zse = ctxt->writer->zs;
	zcbor_state_t *zsd = ctxt->reader->zs;
	bool ok;
	uint32_t index = 0;
	size_t decoded;
	uint16_t total = mgmt_groups_size();
	struct enum_mgmt_single_cb_data cb_data = {
		.current = 0
	};

	struct zcbor_map_decode_key_val enum_single_decode[] = {
		ZCBOR_MAP_DECODE_KEY_DECODER("index", zcbor_uint32_decode, &index),
	};

	ok = zcbor_map_decode_bulk(zsd, enum_single_decode, ARRAY_SIZE(enum_single_decode),
				   &decoded) == 0;

	if (!ok) {
		return MGMT_ERR_EINVAL;
	}

	if (index >= total) {
		/* Requested index is out of bounds */
		(void)smp_add_cmd_err(zse, MGMT_GROUP_ID_ENUM, ENUM_MGMT_ERR_INDEX_TOO_LARGE);
		return MGMT_ERR_EOK;
	}

	cb_data.index = index;
	mgmt_groups_foreach(enum_mgmt_single_cb, &cb_data);

	ok = zcbor_tstr_put_lit(zse, "group") &&
	     zcbor_uint32_put(zse, cb_data.group);

	if (ok && index == (total - 1)) {
		/* When the index represents the final group, reach the end and indicate this in
		 * the response.
		 */
		ok = zcbor_tstr_put_lit(zse, "end") &&
		     zcbor_bool_put(zse, true);
	}

	return ok ? MGMT_ERR_EOK : MGMT_ERR_EMSGSIZE;
}

struct enum_mgmt_details_cb_data {
	zcbor_state_t *zse;
	zcbor_state_t *group_list_zse;
	uint32_t group_list_size;
	int err;
	bool ok;
};

static bool enum_mgmt_details_cb(const struct mgmt_group *group, void *user_data)
{
	struct enum_mgmt_details_cb_data *data = (struct enum_mgmt_details_cb_data *)user_data;
#if defined(CONFIG_MCUMGR_GRP_ENUM_DETAILS_HANDLERS) || \
	defined(CONFIG_MCUMGR_MGMT_NOTIFICATION_HOOKS)
	uint32_t handlers = 0;
#endif
#if defined(CONFIG_MCUMGR_MGMT_NOTIFICATION_HOOKS)
	struct enum_mgmt_detail_output_data detail_output;
	enum mgmt_cb_return status;
	int32_t err_rc;
	uint16_t err_group;
#endif

	if (data->group_list_size > 0) {
		/* Check versus wait list */
		uint32_t i = 0;
		bool found_group = false;
		zcbor_state_t *state = data->group_list_zse;
		zcbor_state_t state_copy;

		memcpy(&state_copy, state, sizeof(zcbor_state_t));

		while (i < data->group_list_size) {
			uint32_t group_id;

			(void)zcbor_uint32_decode(&state_copy, &group_id);

			if (group_id == (uint32_t)group->mg_group_id) {
				found_group = true;
				break;
			}

			++i;
		}

		if (!found_group) {
			return true;
		}
	}

	/* Map represents a single group entry */
	data->ok = zcbor_map_start_encode(data->zse, 4) &&
		   zcbor_tstr_put_lit(data->zse, "group") &&
		   zcbor_uint32_put(data->zse, (uint32_t)group->mg_group_id);

#if defined(CONFIG_MCUMGR_GRP_ENUM_DETAILS_NAME)
	if (group->mg_group_name != NULL) {
		data->ok &= zcbor_tstr_put_lit(data->zse, "name") &&
			    zcbor_tstr_put_term(data->zse, group->mg_group_name,
						CONFIG_MCUMGR_GRP_ENUM_DETAILS_NAME_MAX_LENGTH);
	}
#endif

#if defined(CONFIG_MCUMGR_GRP_ENUM_DETAILS_HANDLERS) || \
	defined(CONFIG_MCUMGR_MGMT_NOTIFICATION_HOOKS)
	while (handlers < group->mg_handlers_count) {
		if (group->mg_handlers[handlers].mh_read != NULL ||
		    group->mg_handlers[handlers].mh_write != NULL) {
			++handlers;
		}
	}
#endif

#if defined(CONFIG_MCUMGR_GRP_ENUM_DETAILS_HANDLERS)
	data->ok &= zcbor_tstr_put_lit(data->zse, "handlers") &&
		    zcbor_uint32_put(data->zse, handlers);
#endif

#if defined(CONFIG_MCUMGR_MGMT_NOTIFICATION_HOOKS)
	if (data->ok) {
		/* Notify listening application callback the status for this entry, it may embed
		 * additional fields safely.
		 */
		detail_output.group = group;
		detail_output.zse = data->zse;

		status = mgmt_callback_notify(MGMT_EVT_OP_ENUM_MGMT_DETAILS, &detail_output,
					      sizeof(detail_output), &err_rc, &err_group);

		if (status != MGMT_CB_OK) {
			if (status == MGMT_CB_ERROR_RC) {
				data->err = err_rc;
			} else {
				(void)smp_add_cmd_err(data->zse, err_group, (uint16_t)err_rc);
				data->err = MGMT_ERR_EOK;
			}

			data->ok = false;

			return false;
		}
	}
#endif

	data->ok &= zcbor_map_end_encode(data->zse, 4);

	return data->ok;
}

/* Lists details on all supported command groups */
static int enum_mgmt_details(struct smp_streamer *ctxt)
{
	zcbor_state_t *zse = ctxt->writer->zs;
	zcbor_state_t *zsd = ctxt->reader->zs;
	uint16_t count = mgmt_groups_size();
	struct enum_mgmt_details_cb_data cb_data = {
		.zse = zse,
		.group_list_zse = NULL,
		.group_list_size = 0,
		.err = -1,
		.ok = true,
	};
	bool ok;
	size_t decoded = 0;
	/* Only the first state of zcbor changes inside a list, a copy can therefore be used to
	 * walk through a list multiple times without needing to use a dedicated array or memory
	 * allocation.
	 */
	zcbor_state_t group_list_zse;
	struct zcbor_map_decode_key_val enum_details_decode[] = {
		ZCBOR_MAP_DECODE_KEY_DECODER("groups", zcbor_list_start_decode, NULL),
	};

	ok = zcbor_map_decode_bulk(zsd, enum_details_decode, ARRAY_SIZE(enum_details_decode),
				   &decoded) == 0;

	if (!ok) {
		return MGMT_ERR_EINVAL;
	}

	if (zcbor_map_decode_bulk_key_found(enum_details_decode, ARRAY_SIZE(enum_details_decode),
					    "groups")) {
		/* Check and validate the group filter list provided by the client */
		memcpy(&group_list_zse, zsd, sizeof(zcbor_state_t));
		cb_data.group_list_zse = &group_list_zse;

		while (!zcbor_array_at_end(zsd)) {
			uint32_t group_id;

			ok = zcbor_uint32_decode(zsd, &group_id);

			if (!ok) {
				return MGMT_ERR_EINVAL;
			}

			++cb_data.group_list_size;
		}

		(void)zcbor_list_end_decode(zsd);

		if (cb_data.group_list_size == 0) {
			/* With an empty group list, return an empty group response */
			ok = zcbor_tstr_put_lit(zse, "groups") &&
			     zcbor_list_start_encode(zse, 0) &&
			     zcbor_list_end_encode(zse, 0);

			return ok ? MGMT_ERR_EOK : MGMT_ERR_EMSGSIZE;
		}
	}

	if (!zcbor_tstr_put_lit(zse, "groups") ||
	    !zcbor_list_start_encode(zse, count)) {
		return MGMT_ERR_EMSGSIZE;
	}

	mgmt_groups_foreach(enum_mgmt_details_cb, &cb_data);

	if (cb_data.err != -1) {
		/* Callback generated an error */
		return cb_data.err;
	}

	if (!cb_data.ok || !zcbor_list_end_encode(zse, count)) {
		return MGMT_ERR_EMSGSIZE;
	}

	return MGMT_ERR_EOK;
}

static const struct mgmt_handler enum_mgmt_handlers[] = {
	[ENUM_MGMT_ID_COUNT] = {
		.mh_read = enum_mgmt_count,
		.mh_write = NULL,
	},
	[ENUM_MGMT_ID_LIST] = {
		.mh_read = enum_mgmt_list,
		.mh_write = NULL,
	},
	[ENUM_MGMT_ID_SINGLE] = {
		.mh_read = enum_mgmt_single,
		.mh_write = NULL,
	},
	[ENUM_MGMT_ID_DETAILS] = {
		.mh_read = enum_mgmt_details,
		.mh_write = NULL,
	},
};

static struct mgmt_group enum_mgmt_group = {
	.mg_handlers = enum_mgmt_handlers,
	.mg_handlers_count = ARRAY_SIZE(enum_mgmt_handlers),
	.mg_group_id = MGMT_GROUP_ID_ENUM,
#if defined(CONFIG_MCUMGR_GRP_ENUM_DETAILS_NAME)
	.mg_group_name = "enum mgmt",
#endif
};

static void enum_mgmt_register_group(void)
{
	mgmt_register_group(&enum_mgmt_group);
}

MCUMGR_HANDLER_DEFINE(enum_mgmt, enum_mgmt_register_group);
